commands.command:
set -eu
printf 'deb [trusted=yes] http://%s:8080 ./\n' "$NODE_IP" | sudo tee /etc/apt/sources.list.d/local-storage.list >/dev/null
sudo sh -c "cat > /etc/apt/apt.conf.d/99-local-repo-offline-test <<EOF
Acquire::http::Proxy \"http://127.0.0.1:9/\";
Acquire::https::Proxy \"http://127.0.0.1:9/\";
Acquire::http::Proxy::$NODE_IP \"DIRECT\";
Acquire::Retries \"0\";
Acquire::http::Timeout \"5\";
Acquire::https::Timeout \"5\";
EOF"
printf 'LOCAL_SOURCE='; cat /etc/apt/sources.list.d/local-storage.list
printf 'REMOTE_PROXY='; apt-config dump | grep -E '^Acquire::(http|https)::Proxy ' | sed 's#http://127.0.0.1:9/#BLOCKED_PROXY/#'
printf 'LOCAL_EXCEPTION='; apt-config dump | grep "Proxy::$NODE_IP"
